INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('894304e4-6c0c-5ec2-914f-55ea9ab178a2', '39bd59db-7196-5c04-a974-242280bc7f6d', 'status', 'Status', 'The lifecycle state of the record. It controls which business actions are normally permitted and how the record is treated by related processes. Used when creating, reviewing, searching, validating, reporting on, or integrating MaintenancePlan records, where applicable. Its meaning is specific to MaintenancePlan; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Represents the draft state or classification in the context of MaintenancePlan. Represents the active state or classification in the context of MaintenancePlan. Represents the suspended state or classification in the context of MaintenancePlan. Represents the retired state or classification in the context of MaintenancePlan. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 1011, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
