INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a4831af6-e6f7-54c5-b9f1-886d8ff273e4', '002bd77f-49f9-5d1a-a659-bb1eca289ac5', '0fd08a53-27bf-530b-bcec-e391854f52dd', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Id', 'Identifies the maintenance plan record associated with this MaintenancePlan. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating MaintenancePlan records, where applicable. Its meaning is specific to MaintenancePlan; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value. Must be unique: a save is rejected if another Maintenance Plan already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
