INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d11c2931-5b17-5163-8bbd-1efd86cd8173', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', 'bfc3d5bc-e9ab-5b35-bdf0-5afb327f6462', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Id', 'The immutable system identity of the maintenance work order. Used for maintenance history, integrations, audit, reporting, scheduling, and traceability across the asset lifecycle. Identifies the work order independently of its business number, Asset, MaintenancePlan, assignee, or RepairEstimate. Required because every maintenance intervention must be uniquely traceable. Must be unique: a save is rejected if another Maintenance Work Order already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('210a5c46-de41-57a1-a78a-cc8145bbbc99', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '7ad734c7-61ca-5c80-b22c-20ca25d7c9fb', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Work Order Number', 'The human-facing reference used by maintenance personnel to identify the work order. Used on maintenance requests, work instructions, technician communications, inspection records, repair documents, and reports. It is a business reference rather than the technical identity and remains the primary operational reference for people. Required so maintenance teams can unambiguously refer to the work instruction. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Maintenance Work Order already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f10ffcee-67b6-55e3-9917-c896eed8708f', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '840511bb-80de-5279-9067-455e7540cf16', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Work Type', 'Classifies the maintenance purpose and determines the general execution method and planning context. Drives maintenance planning, technician assignment, priority, preventive-compliance reporting, repair analytics, and cost analysis. Work type describes why maintenance is being performed; Asset identifies what is being maintained and MaintenancePlan explains recurring planned work when applicable. Examination performed to determine condition, compliance, or the need for further work without necessarily changing the asset. Planned maintenance performed at a defined interval, usage threshold, or condition trigger to reduce the likelihood of failure. Work performed to correct a known condition or restore an asset to its required operating state. Work specifically focused on restoring damaged, defective, or failed components or equipment. Urgent intervention required because an immediate failure, safety concern, operational disruption, or critical condition requires action. Required because maintenance planning and reporting depend on the reason for the work. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0309feca-0f69-50e3-9496-892f89d150d9', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', 'c0278dbd-40f3-58ea-a7e9-c9d741a0eaa0', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Status', 'The controlled lifecycle state of the maintenance work order. Controls scheduling, assignment, execution, escalation, completion, reporting, and downstream asset-history processing. Work-order status describes the maintenance instruction and execution; it does not by itself prove that an Asset is operational, repaired, or returned to service. A valid maintenance need exists but execution has not yet been fully planned. Timing, scope, or resources have been planned sufficiently for execution. Responsibility for performing the work has been allocated to a Party or maintenance team. Maintenance execution has started. Work is temporarily stopped because of parts, access, safety, approval, diagnosis, scheduling, or another blocking condition. The defined work has been performed and accepted according to the applicable completion criteria. The work order has been intentionally terminated without completing the planned work. Required because maintenance processes must know whether work is pending, active, blocked, completed, or terminated. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8066cfb7-1647-5703-a05d-a80cbaf6e827', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '07a852da-3149-55c9-a081-26ff0c54182d', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Priority', 'Indicates the operational urgency with which the maintenance work should be scheduled and executed. Used for dispatching, queue ordering, escalation, resource allocation, service-level monitoring, and maintenance planning. Priority expresses urgency; it is different from workType, which expresses purpose, and from Asset criticality, which expresses the importance of the asset itself. Can normally be scheduled after higher-priority maintenance without significant operational impact. Standard maintenance urgency under normal operational planning. Requires accelerated scheduling because delay may materially affect operations, reliability, or service. Requires immediate or near-immediate attention because delay may create severe safety, operational, financial, or regulatory consequences. Required because maintenance queues need a defined prioritization basis. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f791b30d-e09b-536c-893e-c904a252ca75', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '1e7a62ce-1548-5909-bedf-9579a875c703', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Requested At', 'The date and time when the maintenance need or work request was formally raised. Used for response-time measurement, backlog analysis, SLA monitoring, maintenance history, and audit. It marks demand for maintenance, not necessarily the time work was scheduled, assigned, or started. Required to measure the elapsed time from maintenance demand to execution. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0ebc654e-b259-5f1b-8c85-295fa751eabc', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '6ad22e98-9c10-5a29-91ad-d037c8bb8278', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Scheduled At', 'The planned date and time at which maintenance execution is expected to begin. Used for technician scheduling, asset availability planning, shutdown coordination, parts readiness, and maintenance calendars. It represents a plan and may differ from the actual execution start recorded elsewhere or inferred from status history. Optional while the work remains unscheduled.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f89b048a-88bf-5cf6-a28a-8bb729fb0c61', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '32ecacf5-c22b-5ada-a1eb-faeafbd02c34', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Completed At', 'The date and time at which the maintenance work order was formally completed and accepted. Used for maintenance history, downtime analysis, SLA measurement, compliance reporting, asset availability, and cost closure. Completion means the work-order scope has been accepted; it does not necessarily mean the Asset has returned to service if a separate commissioning or release process exists. Optional until the work is completed.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('eb4840f5-b8b5-5e28-828b-dfd1d80f2af4', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', 'e992c0ca-f0a4-5d05-b4cc-8a5a12c99224', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Description', 'The human-readable statement of the maintenance problem, requested work, observed condition, or intended scope. Provides context to planners, technicians, inspectors, approvers, and downstream reports when structured fields alone cannot capture the maintenance requirement. It complements structured workType, Asset, RepairEstimate, and MaintenancePlan information and should not be used as the sole source for critical machine-readable conditions. Optional when the work scope is fully defined through structured request or task data. Up to 4000 characters.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('49cbbde8-1960-5443-9377-aa154a673bea', '1dbd87c7-c061-5262-9d33-1e8b02465f8b', '26481614-41d3-53ff-b0f9-2c9da115d41f', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Asset', 'Identifies the physical or operational Asset that the maintenance work is intended to inspect, maintain, correct, or repair. Connects maintenance history to asset condition, service intervals, failure history, warranty, depreciation, and operational availability. Zero or one Asset may be recorded when the work concerns a location, general maintenance activity, or an asset not yet identified at request time. Asset answers what is being maintained; MaintenanceWorkOrder answers what work is being requested or performed on it.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
