INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9726d97d-027f-5178-a2d3-df3cfec8d2ef', 'd10916a6-97ef-541a-8257-0d2414718c28', '2347be33-0ce8-566e-b5c9-92b838a522e8', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Id', 'The immutable CEDM identity of the physical container asset. Used as the stable technical-to-business key across yard, movement, repair, inventory, shipment, interchange, leasing, and reporting processes. ContainerMovement, YardSlot, RepairEstimate, Shipment, and Location use this identity to preserve one continuous asset history even as the container changes place, condition, owner, or commercial use. Required because every event and transaction involving equipment must resolve to one unambiguous physical asset. Must be unique: a save is rejected if another Container already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('03bfb572-4f25-5107-9681-2022ff7f5e2d', 'd10916a6-97ef-541a-8257-0d2414718c28', '55b07886-679d-579a-8416-5f4128dd8891', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Container Number', 'The industry-facing identification number assigned to the physical container. Used by carriers, terminals, depots, customs, gate operations, interchange messages, shipping documents, and customers to identify the equipment. It is the operational identifier of the same asset represented internally by containerId; it must remain stable across movements and commercial events. Required because logistics actors normally identify equipment by its container number. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Container already uses this value. Up to 20 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4ec8b267-3d85-5f9e-99b7-1fe7ef656353', 'd10916a6-97ef-541a-8257-0d2414718c28', 'f748d47a-152a-5166-8847-66afdd533c80', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Iso Code', 'The standardized equipment code describing the container''s equipment characteristics. Used for transport compatibility, yard allocation, vessel planning, depot handling, interchange, and equipment classification. Complements containerNumber and informs physical compatibility; it is not itself the container''s identity. Optional only while standardized classification is unavailable; operations requiring equipment compatibility should resolve it before execution. Up to 10 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2ae75eb7-97fc-5810-8e40-8a31364ac272', 'd10916a6-97ef-541a-8257-0d2414718c28', '4ddea2b5-29df-58fd-ba82-261d2fa15834', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Size Code', 'The operational size classification of the container. Used for slot allocation, transport planning, pricing, capacity calculations, and TEU reporting. Size influences physical placement and transport constraints and should remain consistent with the authoritative equipment classification. Optional when derived from isoCode or an equipment master. Up to 20 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('eb3f5351-6efa-534d-bc4c-c1408b2dec17', 'd10916a6-97ef-541a-8257-0d2414718c28', '5e48418e-df60-5584-8658-41e35e8ef233', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Container Type', 'The functional equipment category of the container, such as dry, refrigerated, tank, or open-top equipment. Drives handling, power, inspection, safety, maintenance, shipment compatibility, and yard-placement rules. Type determines operational capabilities and restrictions but does not replace Product or equipment-master classification where standardized definitions exist. Optional when maintained by a controlled equipment master. Up to 50 characters.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2f95f041-4424-5547-bffa-883541af4610', 'd10916a6-97ef-541a-8257-0d2414718c28', '189a831c-a2f6-59e2-95e9-e121dedf3b6a', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Tare Weight', 'The empty weight of the container without cargo. Combined with cargo weight for gross-weight calculations, transport compliance, loading decisions, and interchange. It is an equipment characteristic and should be interpreted with the applicable unit of measure and weighing source. Optional when authoritative equipment specifications provide the value dynamically.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b69ee1f5-a8f7-5d90-8259-f1dba8a7b922', 'd10916a6-97ef-541a-8257-0d2414718c28', '6797f955-b511-5512-9543-56266b944c90', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Max Gross Weight', 'The maximum permitted gross weight of the container and its cargo under the applicable equipment and operating rules. Used for loading, transport planning, safety, vessel/rail/road compliance, and handling decisions. Must be evaluated with tare weight, cargo weight, transport-mode limits, and regulatory constraints. Optional when maintained by an authoritative equipment specification.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bf96d081-4653-5f07-bbd8-6e1820413643', 'd10916a6-97ef-541a-8257-0d2414718c28', 'c938b377-33cf-5e4f-aea0-7466e958d421', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Manufacture Date', 'The date on which the physical container equipment was manufactured. Used for equipment age, inspection, maintenance, depreciation, leasing, resale, and retirement analysis. Commonly combined with acquisition, depreciation, repair, and disposition history to understand economic and operational life. Optional when provenance is incomplete, but its absence limits age-dependent analytics.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6271748c-5220-510b-92ac-d8dafc1c0300', 'd10916a6-97ef-541a-8257-0d2414718c28', 'a7080083-97d5-5f58-9fcb-10441e5e606e', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Status', 'The current lifecycle state governing whether the container is available for ordinary operational use. Controls equipment allocation, yard placement, shipment assignment, repair workflows, disposition, and exception handling. Status is an asset lifecycle state, not a location state or repair estimate result; transitions should be justified by corresponding business processes. Equipment is available for normal assignment subject to operational constraints. Equipment is undergoing repair or maintenance and should normally be excluded from ordinary transport assignment. Equipment has known damage and requires assessment, restriction, or repair before normal use. Ownership or commercial disposition has transferred through a sale process and the equipment is no longer ordinary available inventory unless explicitly returned. Equipment has been designated for disposal and must not be assigned to operational movements. Equipment cannot currently be located and requires investigation or recovery. Equipment has permanently left normal operational service without necessarily being sold or scrapped. Required because equipment availability decisions depend on an explicit lifecycle state. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b52dde90-b22c-5574-9942-eb24bb17dec9', 'd10916a6-97ef-541a-8257-0d2414718c28', '97390150-61c0-5a38-aab4-95a8b75499b8', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Inventory Status', 'The equipment''s inventory classification within the owning or managing organization''s asset inventory process. Supports fleet availability, ownership/lease reporting, depot inventory, and disposition workflows. Inventory classification is distinct from physical condition and lifecycle status and should not be used as a substitute for status. Optional where a dedicated equipment-inventory model supplies the classification. Up to 50 characters.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('28533049-b0d8-5101-9299-8cc14cf0b41a', 'd10916a6-97ef-541a-8257-0d2414718c28', '928a0c6e-78e7-568c-b921-72f145b0fd74', '84af5bc0-d8bc-5df3-b1a1-e2f2a8379b47', 'Owner', 'Identifies the party that owns the physical equipment or is recorded as its commercial owner. Supports asset accounting, leasing, billing, maintenance responsibility, sale, and fleet reporting. At most one owner is represented at a point in time; absence means ownership is not modeled here. Owner is distinct from the carrier, lessee, customer, terminal, depot, or party physically possessing the container.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
