VALUES ('fd46faa2-5ea7-563f-a286-0e38522603e1', 'bus_exchange_rate_status', 'Exchange Rate Status', 'The values of exchange rate status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '2144461f-3ce2-525f-9fac-d2244a37b6be', 'U', TRUE, 'system', 'system', NOW(), NOW())
