VALUES ('89e539db-3cbb-5002-8485-8a641497309d', 'bus_asset_status', 'Asset Status', 'The values of asset status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'b7faa64a-ef2d-5e4f-9ff0-ded878b640ef', 'U', TRUE, 'system', 'system', NOW(), NOW())
