INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('38a12980-958d-531e-9996-1df4612f65d2', 'Repair Estimate Status', 'Maintain Repair Estimate Status records', 'Create, find and maintain Repair Estimate Status records. The list shows every Repair Estimate Status you have access to — select a row to open it, or use New to add one. Each row is a single Repair Estimate Status, described by 6 fields.

Id and Code are unique: no two Repair Estimate Status records may share the same value, and a save that would duplicate one is rejected. Code, Name, Sequence and Is Active must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Repair Estimate Status then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Repair Estimate Status with no rules or workflows attached is marked Final immediately.', 'list', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8f26bf9f-4c86-5524-af62-abb26d3ff8e4', 'bus_repair_estimate_status', 'Repair Estimate Status', 'The values of repair estimate status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '38a12980-958d-531e-9996-1df4612f65d2', 'U', TRUE, 'system', 'system', NOW(), NOW())
