INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5fe2b7d5-4693-5837-8fc4-fcd37b65906e', '97359bac-c631-5f60-9315-080dcf3ae376', 'f53c267a-10ea-5872-a768-2f257e34882a', '88ecf6df-92ef-54fe-a24b-1c26c0a5f435', 'Id', 'The immutable system identity of the estimate line. Used for traceability between the estimate, repair execution, material planning, analytics, and integrations. Identifies one detailed estimate item independently of its parent RepairEstimate, line number, damage, component, or material. Required so every estimated repair requirement can be individually traced. Must be unique: a save is rejected if another Repair Estimate Line already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
