UPDATE sys_table SET sys_category_id = (SELECT sys_category_id FROM sys_category WHERE code = 'reference-data') WHERE table_name IN ('bus_party_party_type', 'bus_party_status', 'bus_person_gender', 'bus_person_party_type', 'bus_person_status', 'bus_organization_organization_type', 'bus_organization_status', 'bus_organization_party_type', 'bus_party_role_role_type', 'bus_party_role_status', 'bus_address_address_type', 'bus_address_status', 'bus_location_location_type', 'bus_location_status', 'bus_currency_status', 'bus_exchange_rate_rate_type', 'bus_exchange_rate_status', 'bus_unit_of_measure_category', 'bus_unit_of_measure_status', 'bus_task_task_type', 'bus_task_status', 'bus_task_priority', 'bus_asset_status', 'bus_maintenance_plan_maintenance_type', 'bus_maintenance_plan_frequency_unit', 'bus_maintenance_plan_status', 'bus_maintenance_work_order_work_type', 'bus_maintenance_work_order_status', 'bus_maintenance_work_order_priority', 'bus_repair_estimate_status', 'bus_repair_estimate_disposition', 'bus_spare_part_criticality', 'bus_container_status', 'bus_product_product_type', 'bus_product_status');
